  'F-03 · SQL-injectie in het loginformulier':
      'F-03 · Vrivanje SQL v prijavnem obrazcu',
  'https://app.voorbeeld/login': 'https://app.example/login',
  'Deze afbeelding naar het AI-model sturen?':
      'Želite to sliko poslati modelu UI?',
  'De afbeelding gaat ongewijzigd naar': 'Slika bo nespremenjena poslana na',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck v sliki ne prekrije ničesar: obrazi, besedilo na posnetku zaslona in vidni podatki gredo zraven.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Preverjanje slik je tu našlo enega ali več prepoznavnih obrazov.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Poleg izvoza nastaneta dve datoteki, s katerima lahko prejemnik preveri prekrivanja.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'našteva, kaj je bilo izpuščeno, brez samih vrednosti. Ta datoteka lahko gre skupaj s poročilom.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'vsebuje ključe, s katerimi je mogoče vsako prekrito vrednost izračunati nazaj. Te datoteke ne pošiljajte zraven: s tem je prekrivanje razveljavljeno. Hranite jo pri viru.',
  'slides': 'prosojnice',
  'Achtergehouden': 'Zadržano',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Zadržano: klasificirano strožje kot predstavitev',
  '1 slide achtergehouden door haar TLP':
      '1 diapozitiv zadržan zaradi svojega TLP',
  'slides achtergehouden door hun TLP':
      'diapozitivov zadržanih zaradi njihovega TLP',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Te prosojnice ne gredo zraven pri predstavljanju, izvozu ali v paketu. Zvišajte raven TLP predstavitve v Informacijah o predstavitvi, da jih vključite.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Vsi diapozitivi so zadržani zaradi svoje klasifikacije TLP — ni kaj prikazati.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Vsi diapozitivi so zadržani zaradi svoje klasifikacije TLP — ni kaj izvoziti.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Vsi diapozitivi so preskočeni ali zadržani zaradi svoje klasifikacije TLP — ni kaj prikazati.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Vsi diapozitivi so preskočeni ali zadržani zaradi svoje klasifikacije TLP — ni kaj izvoziti.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Številke grafikonov niso bile shranjene — obstajajo samo še v tem oknu:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'V brskalniku ni obnovitve po sesutju: če zaprete ta zavihek, je neshranjeno delo izgubljeno. Predstavitev shranite sami.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Lokalna zbirka podatkov CVE (prenos zaženete sami): OciDeck pridobi množične podatke prek api.github.com in datoteke izdaje, na katero kaže ta naslov.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Iskanje CVE (privzeto izklopljeno): ko je vklopljeno, gre vaš iskalni izraz na nastavljeno zrcalo CVE, in če to ničesar ne najde, v evropsko zbirko podatkov ENISA in v MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Vgrajen videoposnetek YouTube ali Vimeo naloži predvajalnik pri tej storitvi.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  V brskalniku: če brskalnik zavrne neposredno pridobitev naslova, OciDeck poskusi znova prek strežnika, s katerega je prišla aplikacija; ta naslov nato pride do tistega strežnika.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Preklic ni bil shranjen. Ob naslednjem zagonu vaše soglasje spet velja.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Naslov razdelka, ki napoveduje nov del predstavitve. Naj bo kratek. Iz knjižnice slik dodajte sliko za ozadje.',
  'Bronnen doorzoeken…': 'Iskanje po virih…',
  'Niet doorzocht': 'Ni preiskano',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'To preverjanje se v spletni različici ne izvaja: zaznavanje obrazov potrebuje sistemsko knjižnico, ki je brskalnik nima. Za preverjanje obrazov na slikah uporabite namizno različico.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Žeton potrebuje pravice za branje in pisanje v repozitorij. Gitea in Forgejo nimata iskanja na strežniku; OciDeck išče lokalno.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Žeton potrebuje obseg repo (ali podrobno: Contents za branje in pisanje).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Žeton potrebuje read_repository, write_repository in read_api. Iskanje na strežniku zahteva Advanced ali Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Hitro iskanje na strežniku — zaradi zakasnitve indeksiranja lahko pravkar spremenjen komplet manjka.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Predstavnostna vsebina se ne ohrani v navadni datoteki .md',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Slike, videoposnetki in zvok, ki ste jih izbrali v tem zavihku, obstajajo samo v pomnilniku. Navadna datoteka .md jih ne ohrani — ob ponovnem odprtju jih ne bo. Izvozite kot paket .ocideck, da vzamete predstavnostno vsebino s seboj.',
  'Media verwijderd om privacyredenen':
      'Predstavnostna vsebina odstranjena zaradi zasebnosti',
  'Afbeeldingen door AI laten taggen?': 'Naj UI označi te slike?',
  'afbeeldingen gaan naar': 'slik bo poslanih na',
  'een model op dit apparaat': 'model v tej napravi',
  'Doorgaan': 'Nadaljuj',
  'Ontdekkingen': 'Odkritja',
  'Wat is gevonden': 'Kaj je bilo najdeno',
  'Soort': 'Vrsta',
  'Dagen onopgemerkt': 'Dni neopaženo',
  'Ontdekking toevoegen': 'Dodaj odkritje',
  'Ontdekking verwijderen': 'Odstrani odkritje',
  'Kop van de slide': 'Naslov prosojnice',
  'dagen onopgemerkt': 'dni neopaženo',
  'Nog geen blootstelling ingevuld — de slide toont dan geen kop, alleen de lijst.':
      'Izpostavljenost še ni vnesena — prosojnica takrat ne prikaže naslova, samo seznam.',
  'Zes ontdekkingen is het maximum; wie er meer noemt maakt een bijlage in plaats van een slide.':
      'Šest odkritij je največ; kdor jih navede več, naredi prilogo namesto prosojnice.',
  'Laat de dagen leeg als de eerste blootstelling onbekend is; de slide zegt dan "onbekend" in plaats van nul. Een lege eigenaar leest als "geen eigenaar" en valt rood op.':
      'Pustite dneve prazne, če je prva izpostavljenost neznana; prosojnica takrat pove "neznano" namesto nič. Prazen nosilec se bere kot "brez nosilca" in izstopa rdeče.',
  'Wat de scan vond dat niemand wist te hebben. Per ontdekking hoe lang die onopgemerkt bereikbaar was en wie hem nu bezit; de langste blootstelling is de kop.':
      'Kar je pregled našel in za kar nihče ni vedel. Po odkritju, kako dolgo je bilo dosegljivo neopaženo in kdo je zdaj nosilec; najdaljša izpostavljenost je naslov.',
  'dag': 'dan',
  'maand': 'mesec',
  'maanden': 'mesecev',
