  'geboortedatum, postcode en geslacht samen — die drie wijzen meestal één persoon aan, ook zonder naam':
      'datum rojstva, poštna številka in spol skupaj — ti trije običajno kažejo na eno osebo, tudi brez imena',
  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Potrdilu tega strežnika ni zaupanja. Pri lastnem strežnika ga lahko pregledaš in mu zaupaš v Nastavitve → Shramba.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Potrdilu tega forge ni zaupanja. Pri lastnem forge ga lahko pregledaš in mu zaupaš v Nastavitve → Shramba.',
  'Het certificaat van het endpoint wordt niet vertrouwd. Bij een zelf gehost endpoint kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Potrdilu tega endpoint ni zaupanja. Pri lastnem endpoint ga lahko pregledaš in mu zaupaš v Nastavitve → Shramba.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Potrdilu forge ni zaupanja — samopodpisano, poteklo ali izdano na drugo ime.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Potrdilu endpoint ni zaupanja — samopodpisano, poteklo ali izdano na drugo ime.',
  'creditcardnummer': 'številka kreditne kartice',
  'beveiligingscode van een creditcard': 'varnostna koda kartice (CVV)',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'podatki v opombah govorca — na prosojnici nevidni, a se izvozijo',
  'Certificaat vertrouwen?': 'Zaupaš temu potrdilu?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Potrdila tega strežnika ni podpisal priznan izdajatelj. Pri lastnem strežniku je to običajno, a tako izgleda tudi prestrežena povezava.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Primerjaj spodnji prstni odtis s tistim, ki ga prikazuje tvoj strežnik. Če se ujemata, govoriš s pravim strojem.',
  'Uitgegeven aan': 'Izdano za',
  'Uitgegeven door': 'Izdal',
  'Geldig tot': 'Velja do',
  'Vingerafdruk (SHA-256)': 'Prstni odtis (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Zaupa se le temu enemu potrdilu. Če ga strežnik pozneje zamenja, bo OciDeck znova vprašal.',
  'Vertrouwen': 'Zaupaj',
  'Certificaat bekijken': 'Prikaži potrdilo',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Mesta, kjer hraniš in prebrskaš svoje predstavitve — mape v tem računalniku, strežniki WebDAV, vedra S3 in skladišča git pomešano. Povleci jih v vrstni red, ki ga želiš: najvišji svoje vrste velja kot privzeti.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Shramba S3: ko se povežeš z vedrom, se shranijo končna točka, ime vedra in tvoj dostopni ključ (skrivni ključ varno v zbirki ključev tvojega sistema), predstavitve, ki jih odpreš ali shraniš, pa se pošljejo tej storitvi shrambe.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Shramba Git: ko se povežeš s skladiščem, se shrani tvoj dostopni žeton (varno v zbirki ključev tvojega sistema), predstavitve, ki jih shraniš, pa se pošljejo temu strežniku kot commiti. Delovna kopija skladišča ostane nešifrirana na tej napravi.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Za jezik te predstavitve manjkajo imena bolezni. Vera, politično prepričanje in sindikalni izrazi so prepoznani, vzorci s kontrolno številko (EMŠO, IBAN, potni list) pa delujejo vedno — vendar ne računajte, da bo diagnoza najdena.',
  'niet getest': 'ni preizkušeno',
  'Werkte op': 'Delovalo je',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Prijavljen si, a tu nimaš dostopa. Geslo ni težava — prosi skrbnika za pravice na tej mapi.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Tvoj žeton je veljaven, a tega ne sme. Daj mu več pravic ali počakaj, če forge uveljavlja omejitev.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Žeton je veljaven, a tega ne sme — daj mu več pravic na repozitoriju.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Prijavljen, a brez dostopa — geslo ni težava. Prosi za pravice na tej mapi.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'To je videti kot celoten DAV URL. Pri Nextcloudu OciDeck to pot izpelje sam — sem sodi samo strežnik.',
  'Overnemen': 'Uporabi',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV ni (pravilno) nastavljen — preveri podatke strežnika v Nastavitve → Shramba.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Repozitorij git ni (pravilno) nastavljen — preveri strežnik, lastnika in repozitorij v Nastavitve → Shramba.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Ime strežnika forgea ne obstaja ali ga ni mogoče poiskati. Preveri, ali je v URL-ju strežnika tipkarska napaka.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Ta forge ima zasebni ali LAN naslov. Označi ga kot zaupanja vrednega internega v Nastavitve → Shramba.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Forge ni dosegljiv — preveri povezavo in URL strežnika.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Prijava v forge ni uspela. Preveri žeton: potrebuje pravico branja repozitorija in pisanja za shranjevanje.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Ni najdeno v repozitoriju — ali pa tvoj žeton tega ne sme videti.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Forge je vrnil napako. Poskusi znova pozneje.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Ta naslov ne odgovarja kot forge. Je vrsta forgea v Nastavitve → Shramba pravilna?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Najprej nastavi strežnik WebDAV v Nastavitve → Shramba.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Potrebno, kadar forge teče v zasebnem ali domačem omrežju. Brez te oznake varnostno preverjanje zavrne zasebni naslov.',
  'Vul server-URL, eigenaar en repository in':
      'Izpolni URL strežnika, lastnika in repozitorij',
  'de standaardbranch heet': 'privzeta veja se imenuje',
  'die wordt voortaan gebruikt': 'ta bo odslej v uporabi',
  'de repository is nog leeg; de eerste opslag vult hem':
      'repozitorij je še prazen; prvo shranjevanje ga bo napolnilo',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'pozor: ta žeton lahko samo bere, zato shranjevanje ne bo uspelo',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'Prijava ni uspela — preveri žeton. Potrebuje pravico branja repozitorija in pisanja, da lahko shranjuje.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Repozitorija ni mogoče najti — ali pa ga tvoj žeton ne sme videti. Preveri lastnika in ime repozitorija.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'Ta naslov ne odgovarja kot forge. Je izbrana vrsta forgea pravilna?',
  'kenteken': 'registrska številka',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'Za jezik te predstavitve ni seznama ključnih besed za posebne vrste osebnih podatkov. Vzorci s kontrolno številko (EMŠO, IBAN, potni list) delujejo; besede kot »diagnoza« ali »osumljenec« niso prepoznane.',
  'Landpakketten voor identificatienummers':
      'Državni paketi za identifikacijske številke',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'Številke, kot sta nizozemska BSN ali poljska PESEL, so vezane na državo. Vsa Evropa je vklopljena, ker ima večina teh številk kontrolno številko: njihov vklop skoraj ne stane lažnih opozoril. IBAN, e-pošta, skrivnosti in potni listi so od tega neodvisni in se vedno preverjajo.',
  'strafrechtelijk gegeven (verdachte)': 'kazenskopravni podatek (osumljenec)',
  'strafrechtelijk gegeven (aangever of slachtoffer)':
      'kazenskopravni podatek (prijavitelj ali žrtev)',
